 BULK_THRESHOLD = 10
BULK_DISCOUNT = 0.9

def line_cost(unit, quantity):
    amount = unit * quantity
    if quantity >= BULK_THRESHOLD:
        amount *= BULK_DISCOUNT
    return amount

def order_total(lines):
    total = 0
    for unit, quantity in lines:
        total += line_cost(unit, quantity)
    return total

def cheapest(lines):
    best = None
    for unit, quantity in lines:
        if best is None or line_cost(unit, quantity) < line_cost(best[0], best[1]):
            best = (unit, quantity)
    return best[0]

def positions_of(target, values):
    found = []
    for i in range(len(values)):
        if values[i] == target:
            found.append(i)
    return found

